def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_d = 0
    opp_c = 0
    my_d = 0
    my_c = 0
    for m, o in history:
        if o == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if m == 'D':
            my_d += 1
        else:
            my_c += 1

    last_me, last_op = history[-1]

    if n == 99:
        return 'D'
    if opp_c == 0:
        return 'D'

    opp_d_streak = 0
    while opp_d_streak < n and history[n - 1 - opp_d_streak][1] == 'D':
        opp_d_streak += 1

    prev_c_streak = 0
    j = n - 1 - opp_d_streak
    while j >= 0 and history[j][1] == 'C':
        prev_c_streak += 1
        j -= 1

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        m, o = history[i]
        if m == 'D' and o == 'D':
            dd_streak += 1
        else:
            break

    dc_streak = 0
    for i in range(n - 1, -1, -1):
        m, o = history[i]
        if m == 'D' and o == 'C':
            dc_streak += 1
        else:
            break

    recent_my_d = 0
    start = n - 4
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][0] == 'D':
            recent_my_d += 1

    recent_opp_c = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_opp_d = (n - start) - recent_opp_c

    recent_opp_c5 = 0
    start5 = n - 5
    if start5 < 0:
        start5 = 0
    for i in range(start5, n):
        if history[i][1] == 'C':
            recent_opp_c5 += 1

    defect_rate = opp_d / n

    if defect_rate > 0.65 and recent_opp_d >= 7:
        if rng.random() < 0.02:
            return 'C'
        return 'D'

    if opp_d == 0:
        if my_d == 0:
            if n >= 98:
                return 'D'
            return 'C'
        if dc_streak >= 2 or n >= 85:
            return 'D'
        if n >= 70 and rng.random() < 0.15:
            return 'D'
        return 'C'

    if last_op == 'D':
        if last_me == 'D':
            if recent_opp_c5 == 0 and opp_d_streak >= 3:
                return 'D'
            if dd_streak >= 2 and recent_opp_c > 0:
                return 'C'
            if opp_d_streak <= 3 and defect_rate < 0.6:
                return 'C'
            if defect_rate < 0.45:
                return 'C'
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        else:
            if recent_opp_c5 == 0 and opp_d_streak >= 3:
                return 'D'
            if opp_d_streak == 1 and (
                recent_my_d > 0 or
                (prev_c_streak >= 3 and defect_rate < 0.55 and opp_d <= 2)
            ):
                return 'C'
            if (
                opp_d_streak == 2 and
                defect_rate < 0.25 and
                prev_c_streak >= 6 and
                opp_d <= 4 and
                rng.random() < 0.1
            ):
                return 'C'
            return 'D'

    if last_me == 'D':
        if dc_streak >= 3:
            return 'D'
        if defect_rate < 0.20 and n >= 80:
            return 'D'
        if (
            defect_rate < 0.35 and
            opp_c > opp_d and
            recent_opp_c >= 2 and
            dc_streak >= 1 and
            rng.random() < 0.18
        ):
            return 'D'
        return 'C'

    if n >= 98 and defect_rate < 0.55:
        return 'D'
    if defect_rate < 0.25 and n >= 90 and rng.random() < 0.3:
        return 'D'
    if rng.random() < 0.015:
        return 'D'
    return 'C'
